DROP TABLE IF EXISTS cnpj_final;

CREATE TABLE "cnpj_final" (
    cnpj text,
    cnpj_basico text,
    matriz_filial text,
    capital_social text,
    ente_federativo_responsavel text,
    razao_social text,
    nome_fantasia text,
    data_inicio_atividades DATE,
    natureza_juridica text,
    descricao_natureza_juridica text,
    qualificacao_responsavel text,
    descricao_qualificacao_responsavel text,
    porte_empresa text,
    descricao_porte_empresa text,
    situacao_cadastral text,
    descricao_situacao_cadastral text,
    data_situacao_cadastral DATE,
    motivo_situacao_cadastral text,
    descricao_motivo_situacao text,
    situacao_especial text,
    data_situacao_especial text,
    tipo_logradouro text,
    logradouro text,
    bairro text,
    cnae_fiscal text,
    cnae_subclasse text,
    cnae_fiscal_secundaria text,
    
    -- 📌 Novas colunas do CNAE
    cnae_secao text,
    cnae_divisao text,
    cnae_grupo text,
    cnae_classe text,
    cnae_subclasse_codigo text,

    -- 📌 Formatação de CEP
    cep_formatado text,
    cep text,
    numero text,
    uf text,
    pais text,
    municipio text,
    opcao_simples text,
    data_opcao_simples text,
    data_exclusao_simples text,
    opcao_mei text,
    data_opcao_mei text,
    data_exclusao_mei text,

    -- 📌 Data de carga
    data_dados text,

    -- 📌 Geolocalização
    distrito VARCHAR(255),
    subprefeitura VARCHAR(255),
    latitude text,
    longitude text
);

INSERT INTO "cnpj_final" 
SELECT 
    es.cnpj_basico || es.cnpj_ordem || es.cnpj_dv AS cnpj, 
    es.cnpj_basico, 
    CASE es.matriz_filial
        WHEN '1' THEN 'MATRIZ'
        WHEN '2' THEN 'FILIAL'
    END AS matriz_filial, 
    em.capital_social,
    em.ente_federativo_responsavel,
    em.razao_social,
    es.nome_fantasia, 
    CASE 
        WHEN LENGTH(es.data_inicio_atividades) = 8 AND es.data_inicio_atividades ~ '^[0-9]+$' 
        THEN TO_DATE(es.data_inicio_atividades, 'YYYYMMDD') 
        ELSE NULL 
    END AS data_inicio_atividades,  
    em.natureza_juridica, 
    nj.descricao AS descricao_natureza_juridica,
    em.qualificacao_responsavel, 
    qs.descricao AS descricao_qualificacao_responsavel,
    em.porte_empresa, 
    CASE em.porte_empresa
        WHEN '00' THEN 'NÃO INFORMADO'
        WHEN '01' THEN 'MICRO EMPRESA'
        WHEN '03' THEN 'EMPRESA DE PEQUENO PORTE'
        WHEN '05' THEN 'DEMAIS'
    END AS descricao_porte_empresa,
    es.situacao_cadastral, 
    CASE es.situacao_cadastral
        WHEN '01' THEN 'NULA'
        WHEN '02' THEN 'ATIVA'
        WHEN '03' THEN 'SUSPENSA'
        WHEN '04' THEN 'INAPTA'
        WHEN '08' THEN 'BAIXADA'
    END AS descricao_situacao_cadastral,
        CASE 
        WHEN LENGTH(es.data_situacao_cadastral) = 8 AND es.data_situacao_cadastral ~ '^[0-9]+$' 
        THEN TO_DATE(es.data_situacao_cadastral, 'YYYYMMDD') 
        ELSE NULL 
    END AS data_situacao_cadastral, 
    es.motivo_situacao_cadastral, 
    m.descricao AS descricao_motivo_situacao, 
    es.situacao_especial, 
    es.data_situacao_especial, 
    es.tipo_logradouro, 
    es.logradouro,  
    es.bairro,
    es.cnae_fiscal, 
    c.descricao AS cnae_subclasse, 
    es.cnae_fiscal_secundaria, 
    -- 📌 Classificação CNAE
    CASE 
		WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 01 AND 03 THEN 'Agricultura, Pecuária, Produção Florestal, Pesca e Aqüicultura'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 05 AND 09 THEN 'Indústrias Extrativas'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 10 AND 33 THEN 'Indústrias de Transformação'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 35 AND 35 THEN 'Eletricidade e Gás'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 36 AND 39 THEN 'Água, Esgoto, Atividades de Gestão de Resíduos e Descontaminação'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 41 AND 43 THEN 'Construção'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 45 AND 47 THEN 'Comércio; Reparação de Veículos Automotores e Motocicletas'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 49 AND 53 THEN 'Transporte, Armazenagem e Correio'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 55 AND 56 THEN 'Alojamento e Alimentação'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 58 AND 63 THEN 'Informação e Comunicação'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 64 AND 66 THEN 'Atividades Financeiras, de Seguros e Serviços Relacionados'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 68 AND 68 THEN 'Atividades Imobiliárias'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 69 AND 75 THEN 'Atividades Profissionais, Científicas e Técnicas'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 77 AND 82 THEN 'Atividades Administrativas e Serviços Complementares'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 84 AND 84 THEN 'Administração Pública, Defesa e Seguridade Social'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 85 AND 85 THEN 'Educação'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 86 AND 88 THEN 'Saúde Humana e Serviços Sociais'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 90 AND 93 THEN 'Artes, Cultura, Esporte e Recreação'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 94 AND 96 THEN 'Outras Atividades de Serviços'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 97 AND 97 THEN 'Serviços Domésticos'
    	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER BETWEEN 99 AND 99 THEN 'Organismos Internacionais e Outras Instituições Extraterritoriais'
    ELSE 'não classificado'
end as cnae_secao,

CASE
 	WHEN LEFT(CAST(cnae_fiscal AS TEXT), 2)::INTEGER = 01 THEN 'Agricultura, Pecuária e Serviços Relacionados'
