    ELSE 'não classificado'
end as cnae_classe,

	c.descricao || ' (' || es.cnae_fiscal || ')' AS cnae_subclasse_codigo,
    CONCAT(LEFT(es.cep, 5), '-', RIGHT(es.cep, 3)) AS cep_formatado,
    es.cep, 
    es.numero,  
    es.uf, 
    es.pais, 
    CASE es.municipio
        WHEN '7107' THEN 'São Paulo'
    END AS municipio,
    CASE s.opcao_simples
        WHEN 'S' THEN 'Sim'
        WHEN 'N' THEN 'Não'
    END AS opcao_simples,
    s.data_opcao_simples, 
    s.data_exclusao_simples, 
    CASE s.opcao_mei
        WHEN 'S' THEN 'Sim'
        WHEN 'N' THEN 'Não'
    END AS opcao_mei,
    s.data_opcao_mei, 
    s.data_exclusao_mei,
    date_trunc('month', current_date)::date AS data_dados,
    d.distrito,
    d.subprefeitura,
    d.latitude,
    d.longitude
    
FROM 
    stg_estabelecimentos es
INNER JOIN 
    stg_empresas em ON es.cnpj_basico = em.cnpj_basico 
INNER JOIN 
    stg_natureza_juridica nj ON em.natureza_juridica = nj.codigo 
INNER JOIN 
    stg_qualificacao_socio qs ON em.qualificacao_responsavel = qs.codigo  
LEFT JOIN  
    stg_simples s ON es.cnpj_basico = s.cnpj_basico 
INNER JOIN
    stg_motivo m ON es.motivo_situacao_cadastral = m.codigo 
INNER JOIN 
    stg_cnae c ON es.cnae_fiscal = c.codigo 

-- A parte a seguir realiza o LEFT JOIN com a tabela de distritos, utilizando a coluna de CEP limpa (sem caracteres não numéricos) para fazer a correspondência. 
-- A subconsulta dentro do LEFT JOIN seleciona o distrito, subprefeitura, latitude e longitude mais frequentes para cada CEP limpo, 
-- garantindo que haja apenas uma correspondência por CEP.
LEFT JOIN (
    SELECT cep_chave, distrito, subprefeitura, latitude, longitude
    FROM (
        SELECT
            COALESCE(
                NULLIF(lpad(regexp_replace(trim(in_postal), '\D', '', 'g'), 8, '0'), '00000000'),
                NULLIF(lpad(regexp_replace(trim(cep), '\D', '', 'g'), 8, '0'), '00000000')
            ) AS cep_chave,
            distrito,
            subprefeitura,
            latitude,
            longitude,
            count(*) AS freq,
            row_number() OVER (
                PARTITION BY COALESCE(
                    NULLIF(lpad(regexp_replace(trim(in_postal), '\D', '', 'g'), 8, '0'), '00000000'),
                    NULLIF(lpad(regexp_replace(trim(cep), '\D', '', 'g'), 8, '0'), '00000000')
                )
                ORDER BY count(*) DESC, distrito, subprefeitura
            ) AS rn
        FROM public.distritos
        GROUP BY
            COALESCE(
                NULLIF(lpad(regexp_replace(trim(in_postal), '\D', '', 'g'), 8, '0'), '00000000'),
                NULLIF(lpad(regexp_replace(trim(cep), '\D', '', 'g'), 8, '0'), '00000000')
            ),
            distrito,
            subprefeitura,
            latitude,
            longitude
    ) x
    WHERE rn = 1
      AND cep_chave IS NOT NULL
) d
    ON lpad(regexp_replace(trim(es.cep), '\D', '', 'g'), 8, '0') = d.cep_chave

WHERE 
    es.municipio = '7107';
   
 
   
  
 
   
